def transform(grid):
    """Extend a solid horizontal bar's trailing background cells in color 1."""
    if not grid or not grid[0]:
        return [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        cols = [c for c, value in enumerate(row) if value != background]
        if not cols:
            continue
        # Extend a single contiguous non-background bar when it ends before the right edge.
        left, right = min(cols), max(cols)
        if len(cols) == right - left + 1 and right < len(row) - 1:
            for c in range(right + 1, len(row)):
                if row[c] != background:
                    break
                out[r][c] = 1
    return out

